import { useEffect, useMemo, useState } from 'react';
import { CheckCircle2, Plus, Search } from 'lucide-react';
import { organizationId, supabase } from '../lib/supabase';
import type { CareNote, Member, Visitor } from '../types';

type Person = Visitor|Member;
export function PeoplePage({type,userId}:{type:'visitor'|'member';userId:string}){const[people,setPeople]=useState<Person[]>([]);const[selected,setSelected]=useState<Person|null>(null);const[query,setQuery]=useState('');const[notes,setNotes]=useState<CareNote[]>([]);const[showAdd,setShowAdd]=useState(false);async function load(){const{data,error}=await supabase.from(type==='visitor'?'visitors':'members').select('*').order('created_at',{ascending:false}).limit(300);if(error)alert(error.message);else setPeople((data||[]) as Person[])}useEffect(()=>{void load()},[type]);useEffect(()=>{if(!selected){setNotes([]);return}void(async()=>{const key=type==='visitor'?'visitor_id':'member_id';const{data}=await supabase.from('care_notes').select('*').eq(key,selected.id).order('created_at',{ascending:false});setNotes((data||[]) as CareNote[])})()},[selected,type]);const filtered=useMemo(()=>people.filter(p=>JSON.stringify(p).toLowerCase().includes(query.toLowerCase())),[people,query]);const name=(p:Person)=>type==='visitor'?(p as Visitor).full_name:`${(p as Member).first_name} ${(p as Member).last_name}`;async function addNote(text:string){if(!selected||!text.trim())return;const key=type==='visitor'?'visitor_id':'member_id';const{error}=await supabase.from('care_notes').insert({organization_id:organizationId,[key]:selected.id,note_text:text.trim(),visibility:type==='visitor'?'assigned_team':'pastoral_team',created_by:userId});if(error)alert(error.message);else setSelected({...selected})}async function markVisited(){if(!selected)return;const key=type==='visitor'?'visitor_id':'member_id';const{error}=await supabase.from('visit_records').insert({organization_id:organizationId,[key]:selected.id,visited_by:userId,outcome:'completed'});alert(error?error.message:'Visit recorded.')}return <><section className="people-layout"><article className="panel people-list"><div className="section-heading"><div><h2>{type==='visitor'?'Visitor':'Member'} database</h2><p>Search, review and update care records.</p></div><button className="primary" onClick={()=>setShowAdd(true)}><Plus/> Add</button></div><label className="search"><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search by name or contact"/></label><div className="rows">{filtered.map(p=><button key={p.id} className={selected?.id===p.id?'selected':''} onClick={()=>setSelected(p)}><span><strong>{name(p)}</strong><small>{(p as Visitor).optional_contact||(p as Member).phone||(p as Member).email||'No contact recorded'}</small></span><span>›</span></button>)}</div></article><article className="panel person-detail">{selected?<PersonDetail personName={name(selected)} notes={notes} onNote={addNote} onVisited={markVisited}/>:<div className="empty">Select a {type} to review visits and care notes.</div>}</article></section>{showAdd&&<AddPerson type={type} userId={userId} close={()=>setShowAdd(false)} done={()=>{setShowAdd(false);void load()}}/>}</>}
function PersonDetail({personName,notes,onNote,onVisited}:{personName:string;notes:CareNote[];onNote:(t:string)=>void;onVisited:()=>void}){const[text,setText]=useState('');return <div><div className="section-heading"><div><h2>{personName}</h2><p>Care and follow-up record</p></div><button className="secondary" onClick={onVisited}><CheckCircle2/> Mark visited</button></div><textarea value={text} onChange={e=>setText(e.target.value)} placeholder="Support needed, prayer request or next action"/><button className="primary" onClick={()=>{onNote(text);setText('')}}>Save note</button><div className="notes">{notes.map(n=><article key={n.id}><p>{n.note_text}</p><small>{new Date(n.created_at).toLocaleString()} · {n.status}</small></article>)}</div></div>}
function AddPerson({type,userId,close,done}:{type:'visitor'|'member';userId:string;close:()=>void;done:()=>void}){async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const row=Object.fromEntries(new FormData(e.currentTarget));const payload={...row,organization_id:organizationId,created_by:userId,...(type==='visitor'?{contact_consent:false}:{})};const{error}=await supabase.from(type==='visitor'?'visitors':'members').insert(payload);if(error)alert(error.message);else done()}return <div className="modal-backdrop"><form className="modal" onSubmit={submit}><h2>Add {type}</h2>{type==='visitor'?<><label>Full name<input name="full_name" required/></label><label>Phone or email<input name="optional_contact"/></label><label>First visit date<input name="first_visit_date" type="date" defaultValue={new Date().toISOString().slice(0,10)} required/></label></>:<><label>First name<input name="first_name" required/></label><label>Last name<input name="last_name" required/></label><label>Email<input name="email" type="email"/></label><label>Phone<input name="phone"/></label></>}<div className="action-row"><button type="button" className="secondary" onClick={close}>Cancel</button><button className="primary">Save</button></div></form></div>}
