import { useState } from 'react';
import { Minus, Plus, RotateCcw, Save, Users } from 'lucide-react';
import { organizationId, supabase } from '../lib/supabase';

export function AttendancePage({userId}:{userId:string}){const[n,setN]=useState(0);const[r,setR]=useState(0);const[history,setHistory]=useState<('new'|'returning')[]>([]);const[service,setService]=useState('Sunday Morning Service');const[busy,setBusy]=useState(false);function add(type:'new'|'returning'){type==='new'?setN(x=>x+1):setR(x=>x+1);setHistory(x=>[...x,type])}function undo(){const last=history.at(-1);if(!last)return;last==='new'?setN(x=>Math.max(0,x-1)):setR(x=>Math.max(0,x-1));setHistory(x=>x.slice(0,-1))}async function save(){setBusy(true);const{error}=await supabase.from('attendance_sessions').insert({organization_id:organizationId,service_name:service,service_date:new Date().toISOString().slice(0,10),new_visitors:n,returning_visitors:r,created_by:userId});setBusy(false);if(error)return alert(error.message);setN(0);setR(0);setHistory([]);alert('Service saved.')}return <><article className="panel service-bar"><label>Service name<input value={service} onChange={e=>setService(e.target.value)}/></label><div><span>Today</span><strong>{new Date().toLocaleDateString()}</strong></div></article><section className="counter-grid"><article className="counter new"><Users/><span>New visitors</span><strong>{n}</strong><button onClick={()=>add('new')}><Plus/> New visitor</button><button className="counter-remove" onClick={()=>setN(x=>Math.max(0,x-1))}><Minus/> Remove</button></article><article className="counter returning"><Users/><span>Returning visitors</span><strong>{r}</strong><button onClick={()=>add('returning')}><Plus/> Returning visitor</button><button className="counter-remove" onClick={()=>setR(x=>Math.max(0,x-1))}><Minus/> Remove</button></article><article className="counter total"><Users/><span>Total attendance</span><strong>{n+r}</strong><p>New {n} · Returning {r}</p></article></section><article className="panel action-row"><button className="secondary" onClick={undo}><RotateCcw/> Undo last</button><button className="primary" disabled={busy} onClick={save}><Save/> {busy?'Saving…':'Save service'}</button></article></>}
