import { useState } from 'react';
import * as XLSX from 'xlsx';
import { FileSpreadsheet, Upload } from 'lucide-react';
import { organizationId, supabase } from '../lib/supabase';

interface ImportRow { first_name:string; last_name:string; email?:string; phone?:string; address?:string; ministry?:string; joined_date?:string; }
export function ImportPage({userId}:{userId:string}){const[rows,setRows]=useState<ImportRow[]>([]);const[busy,setBusy]=useState(false);async function choose(file:File){const wb=XLSX.read(await file.arrayBuffer());const raw=XLSX.utils.sheet_to_json<Record<string,unknown>>(wb.Sheets[wb.SheetNames[0]],{defval:''});setRows(raw.map(x=>({first_name:String(x['First Name']||x.first_name||''),last_name:String(x['Last Name']||x.last_name||''),email:String(x.Email||x.email||''),phone:String(x.Phone||x.phone||''),address:String(x.Address||x.address||''),ministry:String(x.Ministry||x.ministry||''),joined_date:String(x['Date Joined']||x.joined_date||'')})).filter(x=>x.first_name||x.last_name))}async function upload(){setBusy(true);const batch=crypto.randomUUID();const data=rows.map(x=>({...x,organization_id:organizationId,created_by:userId,import_batch_id:batch,imported_at:new Date().toISOString()}));const{error}=await supabase.from('members').insert(data);setBusy(false);if(error)alert(error.message);else{alert(`Imported ${rows.length} members.`);setRows([])}}return <article className="panel import-card"><FileSpreadsheet size={44}/><h2>Import member database</h2><p>Upload an Excel or CSV file with First Name, Last Name, Email, Phone, Address, Ministry and Date Joined columns.</p><label className="file-button"><Upload/> Choose file<input type="file" accept=".xlsx,.xls,.csv" onChange={e=>e.target.files?.[0]&&void choose(e.target.files[0])}/></label>{rows.length>0&&<div className="import-preview"><strong>{rows.length} rows ready</strong><div className="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Ministry</th></tr></thead><tbody>{rows.slice(0,12).map((r,i)=><tr key={i}><td>{r.first_name} {r.last_name}</td><td>{r.email}</td><td>{r.phone}</td><td>{r.ministry}</td></tr>)}</tbody></table></div><button className="primary" disabled={busy} onClick={upload}>{busy?'Importing…':`Import ${rows.length} members`}</button></div>}</article>}
