import { useEffect, useState } from 'react';
import { Check, ShieldCheck, X } from 'lucide-react';
import { supabase } from '../lib/supabase';
import type { UserProfile } from '../types';

export function AdminPage(){const[users,setUsers]=useState<UserProfile[]>([]);async function load(){const{data,error}=await supabase.from('user_profiles').select('*').order('created_at',{ascending:false});if(error)alert(error.message);else setUsers((data||[]) as UserProfile[])}useEffect(()=>{void load()},[]);async function decide(id:string,approve:boolean){const{error}=await supabase.rpc('approve_role_request',{p_user_id:id,p_approve:approve});if(error)alert(error.message);else void load()}return <section className="two-col"><article className="panel"><div className="section-heading"><div><h2>User access approvals</h2><p>Approve or reject pastor access requests.</p></div><ShieldCheck/></div><div className="rows">{users.map(u=><div className="admin-row" key={u.id}><span><strong>{u.display_name}</strong><small>{u.requested_role} · {u.role_status}</small></span>{u.role_status==='pending'&&<span><button className="approve" onClick={()=>decide(u.id,true)}><Check/></button><button className="reject" onClick={()=>decide(u.id,false)}><X/></button></span>}</div>)}</div></article><article className="panel"><h2>Administrator workspace</h2><p>Monitor users, attendance, member imports, care records and role access from this dedicated section.</p><div className="admin-summary"><strong>{users.length}</strong><span>Total registered users</span></div></article></section>}
