import { useEffect, useState } from 'react';
import { ContactRound, HandHeart, Home, Users } from 'lucide-react';
import { supabase } from '../lib/supabase';

export function DashboardPage(){const[stats,setStats]=useState({visitors:0,members:0,care:0,visits:0});useEffect(()=>{void(async()=>{const[v,m,c,x]=await Promise.all([supabase.from('visitors').select('*',{count:'exact',head:true}),supabase.from('members').select('*',{count:'exact',head:true}),supabase.from('care_notes').select('*',{count:'exact',head:true}).neq('status','resolved'),supabase.from('visit_records').select('*',{count:'exact',head:true})]);setStats({visitors:v.count||0,members:m.count||0,care:c.count||0,visits:x.count||0})})()},[]);const cards=[[ContactRound,'Visitors',stats.visitors],[Users,'Members',stats.members],[HandHeart,'Open care needs',stats.care],[Home,'Completed visits',stats.visits]] as const;return <><section className="hero"><small>MINISTRY OVERVIEW</small><h2>One place to welcome, care and follow up.</h2><p>See the responsibilities assigned to your role and keep every next step visible.</p></section><section className="metric-grid">{cards.map(([Icon,label,value])=><article key={label}><Icon/><span>{label}</span><strong>{value}</strong></article>)}</section><section className="two-col"><article className="panel"><h3>Follow-up workflow</h3><p>Register a person, document their support need, and record each completed visit or follow-up.</p></article><article className="panel"><h3>Privacy reminder</h3><p>Record only information needed for appropriate ministry care and limit sensitive notes to the appropriate team.</p></article></section></>}
