import { useState } from 'react';
import { Brand } from '../components/Brand';
import { supabase } from '../lib/supabase';

export function OnboardingPage({defaultName,onDone}:{defaultName:string;onDone:()=>void}){const[role,setRole]=useState<'usher'|'pastor'|null>(null);const[name,setName]=useState(defaultName);const[busy,setBusy]=useState(false);const[error,setError]=useState('');async function save(){if(!role)return;setBusy(true);const{error}=await supabase.rpc('complete_onboarding',{p_display_name:name,p_requested_role:role});if(error)setError(error.message);else onDone();setBusy(false)}return <main className="center-screen"><section className="onboarding-card"><Brand/><h1>Choose your ministry role</h1><p>Ushers manage visitors and attendance. Pastor access includes members, imports and pastoral care, and requires administrator approval.</p>{error&&<div className="notice error">{error}</div>}<label>Display name<input value={name} onChange={e=>setName(e.target.value)}/></label><div className="role-grid"><button className={role==='usher'?'selected':''} onClick={()=>setRole('usher')}><strong>Usher</strong><span>Visitors, attendance and follow-up notes</span></button><button className={role==='pastor'?'selected':''} onClick={()=>setRole('pastor')}><strong>Pastor</strong><span>Members, visitors, imports and pastoral care</span></button></div><button className="primary" disabled={!role||busy} onClick={save}>{busy?'Saving…':'Continue'}</button></section></main>}
